    function installKittyUpgradeModuleUnlock() {
        if (window.__KittyUpgradeModuleUnlockInstalled) return;
        window.__KittyUpgradeModuleUnlockInstalled = true;
        const nativeCall = Function.prototype.call;
        let callProxy = null;
        const restoreCall = () => {
            if (Function.prototype.call === callProxy) Function.prototype.call = nativeCall;
            if (!window.__KittyUpgradeModuleData)
                window.__KittyUpgradeModuleUnlockInstalled = false;
        };
        const unlockData = (data) => {
            if (!data || !Array.isArray(data.weapons) || !Array.isArray(data.list)) return false;
            if (!window.__KittyVanillaUpgradePrerequisites) {
                window.__KittyVanillaUpgradePrerequisites = {
                    weapons: data.weapons.map((entry) => entry && entry.pre),
                    items: data.list.map((entry) => entry && entry.pre)
                };
            }
            data.weapons.forEach((entry) => {
                if (entry && entry.pre != null) entry.pre = null;
            });
            data.list.forEach((entry) => {
                if (entry && entry.pre != null) entry.pre = null;
            });
            window.__KittyUpgradeModuleData = data;
            return true;
        };
        callProxy = new Proxy(nativeCall, {
            apply(target, thisArg, args) {
                try {
                    // Intercept the MooMoo item-data module loader here. Keep
                    // the interception narrow and restore the
                    // native prototype immediately after item module 45 loads.
                    if (args[1] && Number(args[1].i) === 21 && typeof args[3] === "function") {
                        const moduleGetter = args[3];
                        args[3] = function (id) {
                            const data = Reflect.apply(moduleGetter, this, arguments);
                            if (Number(id) === 45 && unlockData(data)) {
                                args[3] = moduleGetter;
                                restoreCall();
                            }
                            return data;
                        };
                    }
                } catch (_) {
                    // The injected runtime has a direct data-module fallback.
                }
                return Reflect.apply(target, thisArg, args);
            }
        });
        Function.prototype.call = callProxy;
        window.setTimeout(restoreCall, 12000);
    }
