            "#kitty-klient-metrics{position:fixed;z-index:2147483645;right:14px;top:62%;transform:translateY(-50%);display:grid;gap:5px;padding:9px 10px;border:1px solid rgba(168,85,247,.68);border-radius:10px;background:rgba(5,3,9,.68);box-shadow:0 0 18px rgba(139,92,246,.38);backdrop-filter:blur(7px);pointer-events:none;color:#fff;font:800 11px/1.15 ui-monospace,SFMono-Regular,Menlo,monospace;text-shadow:0 0 7px #8b5cf6}",
