            "#kitty-klient-update-popup{position:fixed;z-index:2147483647;top:18px;right:18px;width:min(330px,calc(100vw - 36px));box-sizing:border-box;padding:17px 17px 16px;border:1px solid rgba(192,132,252,.82);border-radius:14px;background:linear-gradient(145deg,rgba(8,5,13,.94),rgba(30,12,48,.88));box-shadow:0 0 28px rgba(139,92,246,.5),inset 0 0 22px rgba(168,85,247,.08);backdrop-filter:blur(12px);color:#fff;font:600 13px/1.45 system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;text-shadow:0 0 7px rgba(168,85,247,.8);animation:kitty-update-enter .22s ease-out both}",
