    function setKittyMenuComplexity(level) {
        const next = normalizeKittyMenuComplexity(level);
        if (hudState.menuComplexity === next) {
            renderHud();
            return;
        }
        // Menu complexity belongs to the saved HUD snapshot so a reload or
        // script update leaves the player in the same view.
        applyHudSettings({ menuComplexity: next });
    }

    function refreshKittyCompactControls() {
        const root = document.getElementById(HUD_ID);
        if (!root) return;
        root.querySelectorAll("[data-kitty-compact-setting]").forEach((input) => {
            const key = input.dataset.kittyCompactSetting;
            if (!key) return;
            input.disabled = kittyAccountFeatureLocked(key);
            if (input.type === "checkbox") input.checked = Boolean(hudState[key]);
            else if (document.activeElement !== input) input.value = String(hudState[key] == null ? "" : hudState[key]);
        });
        root.querySelectorAll("[data-kitty-compact-color]").forEach((input) => {
            const key = input.dataset.kittyCompactColor;
            if (!key || document.activeElement === input) return;
            input.value = normalizeHudColor(hudState[key], HUD_DEFAULTS[key]);
        });
        root.querySelectorAll("[data-kitty-compact-group]").forEach((input) => {
            const keys = KITTY_MENU_GROUPS[input.dataset.kittyCompactGroup] || [];
            const enabled = keys.filter((key) => Boolean(hudState[key])).length;
            input.checked = keys.length > 0 && enabled === keys.length;
            // A compact control should always have a clear endpoint. A partly
            // configured group displays off; clicking it turns every option
            // in that group on instead of leaving the thumb in the middle.
            input.indeterminate = false;
            input.setAttribute("aria-checked", String(input.checked));
        });
    }

    function renderKittyMenuComplexityUi() {
        const root = document.getElementById(HUD_ID);
        if (!root) return;
        const level = normalizeKittyMenuComplexity(hudState.menuComplexity);
        root.dataset.kittyMenuComplexity = level;
        root.querySelectorAll("[data-kitty-menu-mode]").forEach((button) => {
            const active = button.dataset.kittyMenuMode === level;
            button.classList.toggle("mm-active", active);
            button.setAttribute("aria-pressed", String(active));
        });
        root.querySelectorAll("[data-kitty-menu-host]").forEach((host) => {
            host.hidden = host.dataset.kittyMenuHost !== level;
        });
        refreshKittyCompactControls();
    }

