        support.append(supportTop, supportIdentity, supportThread, supportEmpty, supportCompose);
        const deleteAccount = document.createElement("details");
        deleteAccount.className = "kitty-account-delete";
        deleteAccount.hidden = true;
        const deleteSummary = document.createElement("summary");
        deleteSummary.textContent = "Account options";
