        deleteBody.className = "kitty-account-delete-body";
        const deleteCopy = document.createElement("p");
        deleteCopy.className = "kitty-account-delete-copy";
        deleteCopy.textContent = "Permanently remove this account. This removes its sessions, verified ranks, bot access, Discord link, rank appeals, and any account-bound rewards. This cannot be undone.";
        const deletePhraseHelp = document.createElement("div");
        deletePhraseHelp.textContent = "Type this confirmation exactly:";
        deletePhraseHelp.className = "kitty-account-delete-copy";
        const deletePhrase = document.createElement("div");
        deletePhrase.className = "kitty-account-delete-phrase";
        const deletePassword = document.createElement("input");
        deletePassword.name = "kitty-account-delete-password";
        deletePassword.type = "password";
        deletePassword.autocomplete = "current-password";
        deletePassword.maxLength = 128;
        deletePassword.placeholder = "Current password";
        const deleteConfirmation = document.createElement("input");
        deleteConfirmation.name = "kitty-account-delete-confirmation";
        deleteConfirmation.type = "text";
        deleteConfirmation.autocomplete = "off";
        deleteConfirmation.maxLength = 28;
        deleteConfirmation.placeholder = "Type the confirmation above";
        deleteConfirmation.spellcheck = false;
