        deleteButton.type = "button";
        deleteButton.dataset.kittyAccountDelete = "1";
        deleteButton.textContent = "Permanently delete account";
        deleteBody.append(deleteCopy, deletePhraseHelp, deletePhrase, deletePassword, deleteConfirmation, deleteButton);
        deleteAccount.append(deleteSummary, deleteBody);
        const status = document.createElement("p");
        status.className = "kitty-account-status";
        status.setAttribute("aria-live", "polite");
