            "#moomoo-op-hud :is(#kitty-klient-account-panel,#kitty-klient-cosmetics-panel)>*{min-width:0;max-width:100%;box-sizing:border-box}",
            "#moomoo-op-hud :is(#kitty-klient-account-panel,#kitty-klient-cosmetics-panel) :is(.kitty-account-form,.kitty-account-support,.kitty-account-discord,.kitty-account-recovery,.kitty-cosmetics-collection){width:100%;min-width:0;box-sizing:border-box}",
            "#moomoo-op-hud :is(#kitty-klient-account-panel,#kitty-klient-cosmetics-panel) :is(.kitty-account-buttons,.kitty-account-discord-actions){display:grid;grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr));gap:10px}",
            "#moomoo-op-hud :is(#kitty-klient-account-panel,#kitty-klient-cosmetics-panel) :is(input,select,textarea){min-width:0;max-width:100%;box-sizing:border-box}#moomoo-op-hud :is(#kitty-klient-account-panel,#kitty-klient-cosmetics-panel) button{white-space:normal;overflow-wrap:anywhere}",
            ".kitty-cosmetics-panel .kitty-weapon-cosmetic-card{grid-template-columns:80px minmax(0,1fr);gap:14px;padding:12px}.kitty-cosmetics-panel .kitty-weapon-cosmetic-preview{width:80px;height:90px}.kitty-cosmetics-panel .kitty-weapon-cosmetic-actions{grid-template-columns:minmax(0,1fr) minmax(110px,.3fr);gap:10px}",
            "@media(max-width:480px){.kitty-cosmetics-panel .kitty-weapon-cosmetic-card{grid-template-columns:64px minmax(0,1fr);gap:10px}.kitty-cosmetics-panel .kitty-weapon-cosmetic-preview{width:64px;height:76px}.kitty-cosmetics-panel .kitty-weapon-cosmetic-actions{grid-template-columns:minmax(0,1fr)}}",
            ".kitty-message-dot{display:inline-block!important;flex:0 0 8px;width:8px;height:8px;margin-left:6px;border-radius:50%!important;background:#fb7185;box-shadow:0 0 5px #fb7185;vertical-align:middle}.kitty-cosmetics-panel .kitty-account-support{width:100%;padding:12px;border:1px solid rgba(192,132,252,.35);box-sizing:border-box}.kitty-cosmetics-panel .kitty-account-support button{padding:7px 10px;border:1px solid #c4b5fd;border-radius:7px;background:#4c1d95;color:#fff;font:800 11px/1.3 system-ui;cursor:pointer}.kitty-cosmetics-panel .kitty-account-support button:disabled{opacity:.5}.kitty-cosmetics-panel .kitty-account-support-top{flex-wrap:wrap}",
            ".kitty-cosmetics-panel{gap:12px!important}",
            ".kitty-cosmetics-panel .kitty-cosmetics-collection{display:grid;gap:7px;padding:11px!important}",
            ".kitty-cosmetics-panel .kitty-cosmetics-collection>span{color:#cbd5e1;font-size:10px;line-height:1.4}",
            ".kitty-cosmetics-chip-list{display:flex;flex-wrap:wrap;gap:6px}",
            ".kitty-cosmetics-chip{padding:5px 8px;border:1px solid var(--kitty-cosmetic-color,#a8a3b7);border-radius:999px;background:color-mix(in srgb,var(--kitty-cosmetic-color,#a8a3b7) 15%,transparent);color:var(--kitty-cosmetic-color,#fff);font:900 10px/1 system-ui,sans-serif;letter-spacing:.04em}",
            ".kitty-cosmetics-empty{color:#94a3b8;font-size:10px}",
            ".kitty-weapon-cosmetic-card{display:grid;grid-template-columns:64px 1fr;gap:10px;align-items:center;padding:8px;border:1px solid rgba(192,132,252,.32);border-radius:9px;background:linear-gradient(135deg,rgba(30,20,52,.62),rgba(5,3,12,.55))}",
            ".kitty-weapon-cosmetic-preview{width:64px;height:76px;object-fit:contain;filter:drop-shadow(0 0 7px rgba(129,140,248,.8))}",
            ".kitty-weapon-cosmetic-card strong{display:block;color:#f5f3ff;font-size:12px}.kitty-weapon-cosmetic-card span{display:block;margin-top:2px;color:#c4b5fd;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.09em}.kitty-weapon-cosmetic-card p{margin:4px 0 0;color:#cbd5e1;font-size:10px;line-height:1.35}",
            ".kitty-weapon-cosmetic-actions{display:grid;grid-template-columns:1fr auto;gap:7px}.kitty-weapon-cosmetic-actions select,.kitty-weapon-cosmetic-actions button,#kitty-klient-cosmetics-panel .kitty-account-discord button{min-height:31px;border:1px solid rgba(196,181,253,.55);border-radius:7px;background:rgba(12,7,23,.76);color:#fff;padding:0 8px;font:800 10px/1 system-ui,sans-serif;text-shadow:none}.kitty-weapon-cosmetic-actions button,#kitty-klient-cosmetics-panel .kitty-account-discord button{cursor:pointer;background:linear-gradient(135deg,#4c1d95,#7c3aed)}#kitty-klient-cosmetics-panel .kitty-account-discord button{padding:7px 10px;line-height:1.3;white-space:normal}#kitty-klient-cosmetics-panel .kitty-account-discord button:hover:not(:disabled){filter:brightness(1.12)}#kitty-klient-cosmetics-panel .kitty-account-discord button:focus-visible{outline:2px solid #c4b5fd;outline-offset:2px}.kitty-weapon-cosmetic-actions :disabled,#kitty-klient-cosmetics-panel .kitty-account-discord button:disabled{opacity:.48;cursor:not-allowed}",
